// Pseudo-skeleton for a COW fault handler
void handle_cow_fault(Process *p, void *fault_addr) {
  Page *shared = get_page(p, fault_addr);
  if (!shared->cow) return; // unexpected
  Page *private = alloc_page();
  copy_page(private, shared->addr);
  // atomically remap fault_addr to private with W permissions
  update_pte(p, fault_addr, private, WRITE);
  decrement_ref(shared);
  flush_tlb(p, fault_addr);
}
```

